import math
def f(N: int, M: int, edges: List[Tuple[int, int, int]]): 
    graph = [[0 for _ in range(N+1)] for __ in range(N+1)]
    for a, b, c in edges:
        graph[a][b] = c
        graph[b][a] = c
    for i in range(1, N+1):
        for j in range(i+1, N+1):
            if graph[i][j] == 0:
                graph[i][j] = float('inf')
                graph[j][i] = float('inf')
    for k in range(1, N+1):
        for i in range(1, N+1):
            for j in range(1, N+1):
                graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j])
    min_val = float('inf')
    for i in range(1, N+1):
        min_val = min(min_val, graph[i][i])
    if min_val == float('inf'):
        return -1
    else:
        return min_val

print(f(3, 3, [(1, 2, 4), (2, 3, 3), (1, 3, 5)]))  # 4
print(f(3, 4, [(1, 2, 4), (2, 3, 3), (1, 3, 5), (2, 3, 2)]))  # -1
print(f(5, 5, [(1, 2, 10), (1, 3, 5), (2, 4, 4), (2, 5, 8), (3, 5, 9)]))  # 4
